  int32 val = 1;
}

"""gRPC KV store server on port 5328."""

from concurrent import futures

import grpc

import kv_store_pb2
import kv_store_pb2_grpc

PORT = 5328


class Server(kv_store_pb2_grpc.KVStoreServicer):
    """Implements the KVStore service backed by a Python dict."""

    def __init__(self):
        self.store = {}

    def GetVal(self, request, context):
        val = self.store.get(request.key, 0)
        return kv_store_pb2.GetValResponse(val=val)

    def SetVal(self, request, context):
        val = request.val
        if not val:
            # tolerate clients that populate `value` instead of `val`
            val = getattr(request, "value", 0) or val
        self.store[request.key] = val
        return kv_store_pb2.SetValResponse(val=val)


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    kv_store_pb2_grpc.add_KVStoreServicer_to_server(Server(), server)
    server.add_insecure_port(f"[::]:{PORT}")
    server.start()
    server.wait_for_termination()


if __name__ == "__main__":
    serve()

